    cin >> N;
    vector<long long> D;
    for(long long x = 1;x <= N/x;x++){
        if(N % x == 0){
            D.push_back(x);
            if(x != N/x){
                D.push_back(N/x);
            }
        }
    }
    sort(D.begin(), D.end());
    for(int i = 0;i < (int)D.size();i++){
        cout << D.at(i) << endl;
    }
    return 0;
}

