#include <bits/stdc++.h>
using namespace std;

int main(){
    int N, Q;
    cin >> N >> Q;
    vector<long long> A(N), S(N+1, 0);
    for(int i = 0;i < N;i++){
        cin >> A.at(i);
        S.at(i+1) = S.at(i) + A.at(i);
    }
    for(int i = 0;i < Q;i++){
        int l, r;
        cin >> l >> r; // 添字l以上r未満
        cout << S.at(r)-S.at(l) << endl;
    }
    return 0;
}
